// Canvas dimensions
const canvasWidth = 400;
const canvasHeight = 400;

// Pendulum parameters
const length = 200; // length of the pendulum
const initialAngle = 45; // initial angle of the pendulum (degrees)
const gravity = 9.8; // acceleration due to gravity (m/s^2)

// Root canvas element
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// Pendulum state
let angle = initialAngle * Math.PI / 180; // convert initial angle to radians
let velocity = 0; // initial velocity

// Button event handler
document.getElementById('release-button').addEventListener('click', () => {
  // Release the pendulum
  window.requestAnimationFrame(tick);
});

// Animation loop
function tick() {
  // Update the pendulum state
  velocity += gravity * Math.sin(angle) / length; // update velocity
  angle += velocity; // update angle

  // Draw the pendulum
  ctx.clearRect(0, 0, canvasWidth, canvasHeight);
  ctx.beginPath();
  ctx.moveTo(canvasWidth / 2, canvasHeight / 2 - length * Math.sin(angle));
  ctx.lineTo(canvasWidth / 2, canvasHeight / 2);
  ctx.stroke();

  // Check if the pendulum has stopped
  if (Math.abs(velocity) < 0.01) { // stop if the velocity is less than 0.01 m/s
    // Reset the pendulum state
    angle = initialAngle * Math.PI / 180;
    velocity = 0;
  } else {
    window.requestAnimationFrame(tick); // continue the animation
  }
}
```
