```typescript
import { BaseApplicationCustomizer } from '@microsoft/sp-core-library';
import { SPComponentLoader } from '@microsoft/sp-loader';

class GTMAppCustomizer extends BaseApplicationCustomizer {
  private gtmContainerId: string;

  constructor() {
    super();
    this.gtmContainerId = process.env.NODE_ENV === 'production' ? (JSON.parse(process.env.NEXT_PUBLIC_CONFIG as string).gtmContainerId) : 'GTM-XXXXX'; // replace with your GTM container ID
  }

  public onInit(): Promise<void> {
    return new Promise<void>((resolve) => {
      SPComponentLoader.loadScript(this.gtmContainerId, 'https://www.googletagmanager.com/gtag/js?id=' + this.gtmContainerId)
        .then(() => {
          // Add the GTM snippet to the page
          const script = document.createElement('script');
          script.src = 'https://www.googletagmanager.com/gtag/js?id=' + this.gtmContainerId;
          script.async = true;
          document.querySelector('head').appendChild(script);
          resolve();
        });
    });
  }
}

export default GTMAppCustomizer;
```
