)

func handler(ctx context.Context) (interface{}, error) {
	ec2Client := ec2.New(session.Must(session.NewSession()))
	tagFilters := []*ec2.Filter{
		{
			Name: aws.String("tag:backup_type"),
		},
	}

	// Get all EBS Snapshots with the "backup_type" tag
	snapshots, err := ec2Client.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filter: tagFilters,
	})
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Delete monthly snapshots (keep the last 14)
	monthlySnapshots := make([]*ec2.Snapshot, 0)
	for _, snapshot := range snapshots.Snapshots {
		if *snapshot.Tags[0].Value == "monthly" {
			monthlySnapshots = append(monthlySnapshots, snapshot)
		}
	}
	for _, snapshot := range monthlySnapshots {
		if len(monthlySnapshots) > 14 {
			_, err = ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(*snapshot.SnapshotId),
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	// Delete daily snapshots (keep the last 10)
	dailySnapshots := make([]*ec2.Snapshot, 0)
	for _, snapshot := range snapshots.Snapshots {
		if *snapshot.Tags[0].Value == "daily" {
			dailySnapshots = append(dailySnapshots, snapshot)
		}
	}
	for _, snapshot := range dailySnapshots {
		if len(dailySnapshots) > 10 {
			_, err = ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(*snapshot.SnapshotId),
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	// Delete weekly snapshots (keep the last 4)
	weeklySnapshots := make([]*ec2.Snapshot, 0)
	for _, snapshot := range snapshots.Snapshots {
		if *snapshot.Tags[0].Value == "weekly" {
			weeklySnapshots = append(weeklySnapshots, snapshot)
		}
	}
	for _, snapshot := range weeklySnapshots {
		if len(weeklySnapshots) > 4 {
			_, err = ec2Client.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(*snapshot.SnapshotId),
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	// Delete yearly snapshot (keep only 1)
	var yearlySnapshot *ec2.Snapshot
	for _, snapshot := range snapshots.Snapshots {
		if *snapshot.Tags[0].Value == "yearly" {
			if yearlySnapshot == nil {
				yearlySnapshot = snapshot
