					SnapshotId: aws.String(*snapshot.SnapshotId),
				})
				if err != nil {
					log.Println(err)
				}
			}
		}
	}

	log.Println("Deleted EBS Snapshots")
	return nil, nil
}

func main() {
	lambda.Start(handler)
}
