#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  gpioInitialise();

  // Set pin 12 as an output
  gpioSetup(12, PI_OUTPUT);

  // Loop indefinitely
  while (1) {
    // Set pin 12 high (1)
    gpioWrite(12, PI_HIGH);

    // Wait for 1 second
    delay(1000);

    // Set pin 12 low (0)
    gpioWrite(12, PI_LOW);

    // Wait for 1 second
    delay(1000);
  }

  // Clean up
  gpioTerminate();
  return 0;
}
