                return "arn:aws:sns:REGION:ACCOUNT_ID:test-preprod-topic";
            case "Prod":
                return "arn:aws:sns:REGION:ACCOUNT_ID:test-prod-topic";
            default:
                throw new InvalidOperationException("Unknown environment");
        }
    }
}
