namespace UPCAGenerator
{
    class Program
    {
        static void Main(string[] args)
        {
            // Enter the product number and weight
            Console.Write("Enter the product number: ");
            string productNumber = Console.ReadLine();
            Console.Write("Enter the product weight (in grams): ");
            int productWeight = Convert.ToInt32(Console.ReadLine());

            // Calculate the UPC-A code
            string upcCode = CalculateUPCCode(productNumber, productWeight);

            // Generate the barcode
            using (Bitmap bitmap = BarcodeWriter.CreateBitmap(upcCode, BarcodeFormat.UPCA, 200, 100))
            {
                bitmap.Save("UPC_A_Barcode.png");
            }

            Console.WriteLine("Barcode generated successfully!");
            Console.ReadLine();
        }

        static string CalculateUPCCode(string productNumber, int productWeight)
        {
            // Check for valid input
            if (productNumber.Length != 12)
            {
                throw new ArgumentException("Product number must be 12 digits long.");
            }

            // Convert the product number to an integer
            int productNumberInt = int.Parse(productNumber);

            // Calculate the UPC-A code
            int modulus10 = (productNumberInt / 1000000000) % 10;
            int modulus9 = (productNumberInt / 10000000) % 10;
            int modulus8 = (productNumberInt / 1000000) % 10;
            int modulus7 = (productNumberInt / 100000) % 10;
            int modulus6 = (productNumberInt / 10000) % 10;
            int modulus5 = (productNumberInt / 1000) % 10;
            int modulus4 = (productNumberInt / 100) % 10;
            int modulus3 = (productNumberInt / 10) % 10;
            int modulus2 = productNumberInt % 10;

            // Calculate the check digit
            int checksum = (modulus10 * 3 + modulus9 * 1 + modulus8 * 3 + modulus7 * 1 +
                            modulus6 * 3 + modulus5 * 1 + modulus4 * 3 + modulus3 * 1 +
                            modulus2 + modulus10 + modulus9 + modulus8 + modulus7 + modulus6 + modulus5 + modulus4 + modulus3) % 10;
            checksum = (checksum == 0) ? 0 : 10 - checksum;

            // Return the UPC-A code
            return productNumber + checksum.ToString();
        }
    }
}
```

