function TravelApp() {
  const [destinations, setDestinations] = useState([]);
  const [newDestination, setNewDestination] = useState('');
  const [errorMessage, setErrorMessage] = useState(null);

  const handleAddDestination = (event) => {
    event.preventDefault();
    if (!newDestination) {
      setErrorMessage('Please enter a destination');
    } else {
      setDestinations([...destinations, { name: newDestination, description: '', image: '' }]);
      setNewDestination('');
      setErrorMessage(null);
    }
  };

  const handleDeleteDestination = (index) => {
    setDestinations(destinations.filter((destination, i) => i !== index));
  };

  return (
    <div>
      <h1>Travel App</h1>
      <form onSubmit={handleAddDestination}>
        <input
          type="text"
          value={newDestination}
          onChange={(event) => setNewDestination(event.target.value)}
          placeholder="Add a destination"
        />
        <button type="submit">Add</button>
      </form>
      {errorMessage && <p style={{ color: 'red' }}>{errorMessage}</p>}
      <ul>
        {destinations.map((destination, index) => (
          <li key={index}>
            <h2>{destination.name}</h2>
            <p>{destination.description}</p>
            <img src={destination.image} alt={destination.name} />
            <button onClick={() => handleDeleteDestination(index)}>Delete</button>
