Here is a C++ program that renames every file inside a folder with a 3-digit number, sorted by file creation date:
```cpp
#include <iostream>
#include <filesystem>
#include <algorithm>
#include <sstream>
#include <iomanip>
#include <ctime>

int main() {
    // Get the folder path from the user
    std::string folderPath;
    std::cout << "Enter the folder path: ";
    std::cin >> folderPath;

    // Create a directory iterator to iterate over the files in the folder
    std::filesystem::directory_iterator endIter;
    for (auto& file : std::filesystem::directory_iterator(folderPath)) {
        // Get the file creation time
        std::time_t creationTime = file.status().last_write_time();

        // Get the file name
        std::string fileName = file.path().filename().string();

        // Extract the file extension
        std::size_t dotPos = fileName.find('.');
        std::string fileExtension = dotPos != std::string::npos ? fileName.substr(dotPos) : "";

        // Sort the files by creation time
        std::vector<std::pair<std::time_t, std::string>> files;
        files.emplace_back(creationTime, fileName);
        for (auto& f : files) {
            std::cout << f.first << " " << f.second << std::endl;
        }
        std::sort(files.begin(), files.end());

        // Rename the files with a 3-digit number, sorted by creation time
        int count = 0;
        for (auto& f : files) {
            std::ostringstream oss;
            oss << std::fixed << std::setfill('0') << std::setw(3) << ++count << fileExtension;
            std::string newFileName = oss.str();
            file.rename(folderPath + "/" + newFileName);
            std::cout << "Renamed " << f.second << " to " << newFileName << std::endl;
        }
    }

    return 0;
}
```
