class VectorDatabase:
    dimension = 128  # static constant for faiss index dimension

    def __init__(self, index_file):
        self.index_file = index_file
        if not os.path.exists(index_file):
            self.index = faiss.IndexFlatL2(VectorDatabase.dimension)
        else:
            with open(index_file, 'rb') as f:
                self.index = pickle.load(f)

    def __del__(self):
        self.save_index()

    def _get_embedding(self, item):
        # Implement conversion from item to numpy array
        # For now, return a random numpy array
        import numpy as np
        return np.random.rand(VectorDatabase.dimension)

    def add_item(self, item):
        emb = self._get_embedding(item)
        self.index.add_with_ids(np.array([emb]), [self.index.ntotal])

    def get_item(self, id):
        try:
            item = self.index.reconstruct(int(id))
            return item
        except Exception:
            return None

    def remove_item(self, id):
        try:
            self.index.remove_ids([int(id)])
        except Exception:
            pass

    def save_index(self):
        with open(self.index_file, 'wb') as f:
            pickle.dump(self.index, f)

    def list_items(self):
        for i in range(self.index.ntotal):
            item = self.index.reconstruct(i)
            print(f"{i}: {item}")

    def search(self, query, k):
        emb = self._get_embedding(query)
        distances, indices = self.index.search(np.array([emb]), k)
        results = []
        for i, idx in enumerate(indices[0]):
            results.append((self.get_item(idx), distances[0][i]))
        return results

