```
pragma solidity ^0.8.0;

import "https://github.com/OpenZeppelin/openzeppelin-solidity/contracts/token/ERC721/SafeERC721.sol";

contract FixedSupplyNFT {
    // Event emitted when a new NFT is minted
    event NewNFT(address indexed owner, uint256 tokenId);

    // Mapping of NFT token IDs to their owners
    mapping (uint256 => address) public NFTOwners;

    // Mapping of NFT token IDs to their metadata
    mapping (uint256 => string) public NFTMetadata;

    // Mapping of NFT token IDs to their base URI
    string public baseURI = "https://example.com/nft/";

    // Total supply of NFTs
    uint256 public totalSupply;

    // Number of NFTs currently available for sale
    uint256 public availableSupply;

    // Mapping of NFT token IDs to their prices
    mapping (uint256 => uint256) public NFTPrices;

    // Constructor function
    constructor() public {
        totalSupply = 1000; // 1000 NFTs in the collection
        availableSupply = totalSupply;
    }

    // Function to mint a new NFT
    function mintNFT(address payable _owner, uint256 _tokenId, string memory _metadata) public {
        require(availableSupply > 0, "All NFTs have been sold");
        require(NFTOwners[_tokenId] == address(0), "NFT already exists");

        // Update availableSupply
        availableSupply -= 1;

        // Set NFT owner and metadata
        NFTOwners[_tokenId] = _owner;
        NFTMetadata[_tokenId] = _metadata;

        // Emit event
        emit NewNFT(_owner, _tokenId);

        // Set NFT price
        NFTPrices[_tokenId] = 0.1 ether; // example price of 0.1 ETH
    }

    // Function to burn an NFT
    function burnNFT(uint256 _tokenId) public {
        require(NFTOwners[_tokenId] != address(0), "NFT does not exist");
        require(NFTPrices[_tokenId] > 0, "NFT has been burned");

        // Update availableSupply
        availableSupply += 1;

        // Set NFT owner to 0 (burned)
        NFTOwners[_tokenId] = address(0);

        // Set NFT price to 0 (burned)
        NFTPrices[_tokenId] = 0;
    }

    // Function to get NFT metadata
    function getNFTMetadata(uint256 _tokenId) public view returns (string memory) {
        return NFTMetadata[_tokenId];
    }

    // Function to get NFT price
    function getNFTPrice(uint256 _tokenId) public view returns (uint256) {
        return NFTPrices[_tokenId];
    }
}
```
