import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ListView;
import android.widget.Toast;

import java.util.ArrayList;
import java.util.List;

public class ShopActivity extends AppCompatActivity {

    private ListView listView;
    private EditText itemNameEditText;
    private EditText itemPriceEditText;
    private Button addButton;
    private Button deleteButton;
    private Button modifyButton;
    private ShopDBHelper shopDBHelper;

    private List<Item> items;
    private ArrayAdapter<Item> adapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_shop);

        listView = findViewById(R.id.list_view);
        itemNameEditText = findViewById(R.id.item_name_edit_text);
        itemPriceEditText = findViewById(R.id.item_price_edit_text);
        addButton = findViewById(R.id.add_button);
        deleteButton = findViewById(R.id.delete_button);
        modifyButton = findViewById(R.id.modify_button);

        shopDBHelper = new ShopDBHelper(this);
        items = new ArrayList<>();

        adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, items);
        listView.setAdapter(adapter);

        addButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                addItem();
            }
        });

        deleteButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                deleteItem();
            }
        });

        modifyButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                modifyItem();
            }
        });
    }

    private void addItem() {
        String itemName = itemNameEditText.getText().toString();
        String itemPrice = itemPriceEditText.getText().toString();

        if (!itemName.isEmpty() && !itemPrice.isEmpty()) {
            double price = Double.parseDouble(itemPrice);
            Item item = new Item(itemName, price);
            shopDBHelper.addItem(item);
            items.add(item);
            adapter.notifyDataSetChanged();
            itemNameEditText.setText("");
            itemPriceEditText.setText("");
        } else {
            Toast.makeText(this, "Please fill in all fields", Toast.LENGTH_SHORT).show();
        }
    }

    private void deleteItem() {
        int position = listView.getSelectedItemPosition();
        if (position != -1) {
            Item item = items.get(position);
            shopDBHelper.deleteItem(item);
            items.remove(position);
            adapter.notifyDataSetChanged();
        }
    }

    private void modifyItem() {
        int position = listView.getSelectedItemPosition();
        if (position != -1) {
            Item item = items.get(position);
            String itemName = itemNameEditText.getText().toString();
            String itemPrice = itemPriceEditText.getText().toString();

            if (!itemName.isEmpty() && !itemPrice.isEmpty()) {
                double price = Double.parseDouble(itemPrice);
                item.setName(itemName);
                item.setPrice(price);
                shopDBHelper.updateItem(item);
                items.set(position, item);
                adapter.notifyDataSetChanged();
                itemNameEditText.setText("");
                itemPriceEditText.setText("");
            } else {
                Toast.makeText(this, "Please fill in all fields", Toast.LENGTH_SHORT).show();
            }
        }
    }
}
