**ShopDBHelper.java**
```java
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;

import java.util.ArrayList;
import java.util.List;

public class ShopDBHelper extends SQLiteOpenHelper {

    private static final String DATABASE_NAME = "shop.db";
    private static final int DATABASE_VERSION = 1;

    public ShopDBHelper(Context context) {
        super(context, DATABASE_NAME, null, DATABASE_VERSION);
    }

    @Override
    public void onCreate(SQLiteDatabase db) {
        db.execSQL("CREATE TABLE items (_id INTEGER PRIMARY KEY, name TEXT, price REAL);");
    }

    @Override
    public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
        db.execSQL("DROP TABLE IF EXISTS items");
        onCreate(db);
    }

    public void addItem(Item item) {
        SQLiteDatabase db = this.getWritableDatabase();
        db.execSQL("INSERT INTO items (name, price) VALUES ('" + item.getName() + "', " + item.getPrice() + ");");
    }

    public void deleteItem(Item item) {
        SQLiteDatabase db = this.getWritableDatabase();
        db.execSQL("DELETE FROM items WHERE _id = " + item.getID());
    }

    public void updateItem(Item item) {
        SQLiteDatabase db = this.getWritableDatabase();
        db.execSQL("UPDATE items SET name = '" + item.getName() + "', price = " + item.getPrice() + " WHERE _id = " + item.getID());
    }

    public List<Item> getAllItems() {
        SQLiteDatabase db = this.getReadableDatabase();
        Cursor cursor = db.query("items", new String[]{"_id", "name", "price"}, null, null, null, null, null);

        List<Item> items = new ArrayList<>();
        while (cursor.moveToNext()) {
            int id = cursor.getInt(0);
            String name = cursor.getString(1);
            double price = cursor.getDouble(2);
            Item item = new Item(id, name, price);
            items.add(item);
        }
        cursor.close();
        return items;
    }
}
