    theta2_control = -Kp * e_y - Kd * (e_y - last_e_y);

    % Update the control output and the simulation variables
    theta1 = theta1 + theta1_control;
    theta2 = theta2 + theta2_control;
    last_e_x = e_x;
    last_e_y = e_y;

