import { useLocation } from 'react-router-dom';
import { Table } from 'react-table';
import { TansackTable } from 'tansack-table';

const FilteredTable = ({ columns, data }) => {
  const [filters, setFilters] = useState({});
  const location = useLocation();
  const history = useHistory();
  const { getTableProps, getTableBodyProps } = useTable({ columns, data });

  useEffect(() => {
    const	currentFilters = getFiltersFromUrl(location.search);
    setFilters(currentFilters);
  }, [location.search]);

  const getFiltersFromUrl = (searchParams) => {
    const filters = {};
    searchParams.forEach((param, value) => {
      filters[param.substring(1)] = { value };
    });
    return filters;
  };

  const handleFilterChange = (column, value) => {
    setFilters((prevFilters) => ({ ...prevFilters, [column]: { value } }));
    const updatedSearchParams = updateSearchParams(location, filters);
    history.replace(updatedSearchParams);
  };

  return (
    <TansackTable
      {...getTableProps()}
      bodyProps={{ ...getTableBodyProps() }}
      columns={columns}
      data={data}
      filters={filters}
      onFilterChange={handleFilterChange}
    />
  );
};
```
In this example, we're using the `useState` hook to store the current column filters, and `useEffect` to update the filters when the URL search params change.

